import '../models/file_output.dart';

abstract class GeneratorBase {
  List<FileOutput> generate();

  /// Returns the standard header for generated files.
  String getGeneratedFileHeader() {
    return '// GENERATED CODE - DO NOT MODIFY BY HAND\n// Generated by abidock_mvx code generator\n\n';
  }

  /// Escapes angle brackets in contract-supplied documentation prose.
  ///
  /// Contract docs routinely name generic types such as `ManagedVec<T>`.
  /// Copied verbatim into a `///` comment those read as HTML tags, which
  /// both mangles the rendered output and trips the
  /// `unintended_html_in_doc_comment` lint in the user's project.
  ///
  /// Text inside a backtick code span is left untouched: markdown renders
  /// it literally, so escaping there would surface `&lt;` to the reader.
  ///
  /// #### Parameters
  /// - `line` - A single line of documentation taken from the ABI.
  ///
  /// #### Returns
  /// The line, safe to emit inside a `///` comment.
  String escapeDocLine(String line) {
    final buffer = StringBuffer();
    var index = 0;

    for (final match in RegExp(r'`[^`]*`').allMatches(line)) {
      buffer.write(_escapeAngleBrackets(line.substring(index, match.start)));
      buffer.write(match.group(0));
      index = match.end;
    }
    buffer.write(_escapeAngleBrackets(line.substring(index)));

    return buffer.toString();
  }

  String _escapeAngleBrackets(String text) =>
      text.replaceAll('<', '&lt;').replaceAll('>', '&gt;');
}
